<?= $this->extend('layouts/main') ?><?= $this->section('content') ?><div class="page-head"><h1>Products</h1><a class="button primary" href="<?= site_url('products/create') ?>">Add Product</a></div><div class="panel"><table><thead><tr><th>Image</th><th>Name</th><th>Price</th><th>Stock</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><?php if($p['image']): ?><img class="thumb" src="<?= base_url('uploads/products/'.$p['image']) ?>" alt=""><?php else: ?><span class="placeholder">No image</span><?php endif ?></td><td><?= esc($p['name']) ?></td><td>₱<?= number_format((float)$p['price'],2) ?></td><td><?= $p['stock_quantity'] ?></td><td><?= $p['is_active']?'Active':'Archived' ?></td><td><a href="<?= site_url('products/'.$p['id'].'/edit') ?>">Edit</a><?php if($p['is_active']): ?><form class="inline" method="post" action="<?= site_url('products/'.$p['id'].'/archive') ?>" onsubmit="return confirm('Archive this product?')"><?= csrf_field() ?><button class="danger link">Archive</button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?= $this->endSection() ?>
